WF.options=function(){const STORAGE_KEY="wf_checklist_options",DEFAULTS={includeOptionsInExport:!1,includeSyncKeyInExport:!1,includeFounderItems:!1,includePvpItems:!1,syncKey:null};let _cache=null;return window.addEventListener("storage",(event=>{event.key===STORAGE_KEY&&(_cache=null)})),{load:function(){if(_cache)return _cache;try{const raw=localStorage.getItem(STORAGE_KEY);_cache=raw?{...DEFAULTS,...JSON.parse(raw)}:{...DEFAULTS}}catch(err){console.error("Unreadable or corrupted localStorage options, reset.",err),_cache={...DEFAULTS}}return _cache},save:function(optionsMap){const sanitized={...optionsMap,themeColors:WF.theme?WF.theme.sanitizeColors(optionsMap.themeColors):{}};_cache=sanitized;try{localStorage.setItem(STORAGE_KEY,JSON.stringify(sanitized))}catch(err){console.error("Failed to save options to localStorage.",err),WF.toast&&WF.toast.show("Options could not be saved: browser storage is full.",{type:"error",key:"wf-options-full"})}},DEFAULTS:DEFAULTS,STORAGE_KEY:STORAGE_KEY}}();